vm=Path('/Users/dowling/projects/nupp/.nupp-cache/toolchain/146f4035337ca7ca/luajit/bin/luajit')
out=Path('/private/tmp/nupp-63-events-carry-window-final-formal');out.mkdir(exist_ok=False)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
