entire125-second batch. Frozen artifacts, per-process measurement, numerical thresholds and analysis are unchanged. No earlier observations are reclassified or reused.','analysis':'Per-process median paired sample log throughput ratios; mean and Student t95% interval across25eligible independent processes. All attempts retained and environmental exclusions explicit.','hashes':{str(p):sha(p) for p in files},'script':Path(__file__).read_text()}
(out/'protocol.json').write_text(json.dumps(protocol,indent=2)+'\n')
env=os.environ.copy();env['LUA_PATH']=str(candidate)+'/?.lua;'+str(candidate)+'/?/init.lua;'+str(root)+'/build/?.lua;'+str(root)+'/.rocks/share/lua/5.1/?.lua;'+str(root)+'/.rocks/share/lua/5.1/?/init.lua;;';env['LUA_CPATH']=str(root)+'/.rocks/lib/lua/5.1/?.so;;';env['NUPP_FUSED_BASELINE']=str(baseline);env['NUPP_FUSED_BENCH_BATCH_BYTES']='67108864'
