started=time.monotonic();attempt=0;proc=None;firstlaunch=None;quietSince=None
with (out/'environment.jsonl').open('w') as observations:
 def observe(phase):
  global quietSince
  bad=[]
  for line in subprocess.check_output(['ps','-Ao','pid,pcpu,comm'],text=True).splitlines()[1:]:
   a=line.split(None,2)
   if len(a)!=3:continue
   pid,cpu,command=int(a[0]),float(a[1]),Path(a[2]).name
   try: own=proc is not None and os.getpgid(pid)==proc.pid
   except ProcessLookupError:continue
   if not own and (command in compilers or cpu>5 and (command in {'luajit','lua'} or command.startswith('nupp'))):bad.append(command)
  if bad:quietSince=None
  elif quietSince is None:quietSince=time.monotonic()
  result={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'phase':phase,'attempt':attempt,'interference':sorted(set(bad))}
