    attempt+=1
    if firstlaunch is None:firstlaunch=time.monotonic()
    if attempt>150:raise SystemExit('Attempt budget exhausted; all attempts retained.')
    name=f'attempt-{attempt:03d}-{payload}-{fork:02d}';directory=out/name;directory.mkdir()
    env['NUPP_FUSED_BENCH_PAYLOAD']=payload;env['NUPP_FUSED_BENCH_OUTPUT']=str(directory/'result.json')
    bad=False;begin=datetime.datetime.now(datetime.timezone.utc).isoformat()
    with (directory/'output.log').open('w') as log:
     proc=subprocess.Popen([str(vm),str(root/'bench/fused-json/tests/bench.lua'),'25'],cwd=root/'bench/fused-json',env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
     while proc.poll() is None:
      if time.monotonic()>firstlaunch+900:
       os.killpg(proc.pid,signal.SIGTERM);proc.wait()
       (directory/'eligibility.json').write_text(json.dumps({'eligible':False,'reason':'measurement deadline exhausted','attempt':attempt,'fork':fork,'payload':payload})+'\n')
       raise SystemExit('Environment qualification time budget exhausted; all attempts retained.')
      bad=observe('measurement') or bad;time.sleep(.2)
     code=proc.returncode
    record={'attempt':attempt,'fork':fork,'payload':payload,'started_utc':begin,'exit_code':code,'interference':bad,'eligible':not bad and code==0,'directory':name}
    (directory/'eligibility.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record),flush=True)
    if code:raise SystemExit('Benchmark failed; no semantic failures are retried.')
    if not bad:
     (out/f'{payload}-{fork:02d}.json').write_bytes((directory/'result.json').read_bytes())
     (out/f'{payload}-{fork:02d}.log').write_bytes((directory/'output.log').read_bytes())
     break
assert all(sha(Path(p))==v for p,v in protocol['hashes'].items())
(out/'environment-qualified.json').write_text(json.dumps({'qualified':True,'eligible_processes':75,'attempts':attempt,'seconds':time.monotonic()-started},indent=2)+'\n')
print('Environment qualification complete; numerical gates remain to analyze.',flush=True)

